	title 'Print Manager'****************************************************************************************	 Copyright Apple Computer, Inc. 1986-1989,1991*	            All Rights Reserved*******************************************************************************************************************************************************************************	  The Print Manager*	    Tool019** Coding Started Summer 1986 by Luc Barthelet and VersionSoft** 16 March 1987  Steven Glass** Reorginize tool to be more the way we	like it.  Use list mgr* for chooser to save code.*** Version 1.0   April 10, 1987   Steven	Glass** Version 1.1   May	7, 1987    Suki Lee**    Checks for boot disk before calling loader when loading*    drivers so loader won't display insert disk message.** Version 1.2   1987    Suki Lee**    Added new tool	call PrBitMap to dump a bitmap to the*    printer.** Version 2.0d1  Nov 25, 1987    Harry Yee   (System Disk v3.2d3)** Version 2.0d2  Dec 03, 1987    Harry Yee   (System Disk v3.2d4)** Version 2.0d3*   11 Dec 87    Rob Turner reported bug that MultiScribe would not boot.*                The routines Dispatch and DPort were not setting the data*                bank register. Because	the order of when and where drivers*                were being loaded has changed from v1.0 of	the print mgr the*                routines mentioned never had to set the data bank reg.** Version 2.0    Mar 01, 1988    Harry Yee   (System Disk v3.1.1)** Version 2.1d1	*                Added code to check if AppleTalk selected in the control *                panel when in the AppleTalk chooser screen.** Version 2.1d2  June 02, 1988   Harry Yee*                Problem with editline item in Chooser Dialog. Editline length *                was 16 chars. yet the space allocated for it was only 15. *                Therefore if the user used all 16 chars. it would overwrite by*                one byte what was allocated directly after the user name space,*                which was the netname.  The max. allowable user name is now 15.** Version 2.1d3  June 07, 1988    Harry Yee*                Fixed problem of being able to select a printer in a different*                zone, with the same name as the printer currently selected.*                Choose Printer would, in the chooserfilter filterproc compare *                printer names, and if they didn't change I assumed the zone *                didn't change either. Now I check if the zones changed and if*                they did and the user clicked in the printer names list, I *                record this new selection.**                The result passed back from PrChoosePrinter is now correct. When*                the user presses the 'OK' button the result is True, if the user*                presses the 'Cancel' button the result is False. This works the *                same as it always had.(i.e. pressing 'OK' even though no driver*                changes still returns True.)** Version 2.1    June 14, 1988     Harry Yee*                Changed string in dialogdata.asm from 'Choose Printer v2.1d3' to *                ' Choose Printer v2.1 '. Spaces left in so string stays the same *                length. PrinterMgr.equ version # changed from $8201 to $0201.**                June 22, 1988     Harry Yee*                In DummyPrinter routine changed a jsr PostAlert to a jsl PostAlert.**                June 23, 1988     Harry Yee*                Made change to PMStartup, if an error was returned from SetupDriverList*                then that means while opening the Drivers folder ProDOS returned*                an error, e.g. path not found, etc,...**                If no printer or port drivers are in the Drivers folder then there *                is a chance that memory gets trashed. Two handles are allocated for *                the printer and port lists. e.g. if no port drivers are found then *                the list is empty. But in setting up the default values i.e. first *                driver in each list is selected when you get into the Choose Dialog,*                I assume that there is at least one driver in each list.  So I go *                and find the first item in this empty list, getting a length byte *                which is some random value and then procede to copy it some storage *                location.  A large value would therefore trash more than was allocated *                for the location I am copying into to.*                Checks are being made in DefaultPrinter and DefaultPort now to see if *                the printer or port lists are empty. If they are empty then I just *                return, since an empty list means there is not going to be a default value.**                June 24, 1988     Harry Yee*                When a driver call is made that particular driver is loaded by the print *                mgr. When a printer driver call is made the print mgr makes sure that there*                is a corresponding port driver that has been selected. The check to see if *                this port driver existed failed if there was an empty driver list and the *                printer.setup had not been created yet. ** Version 2.2d1  July 12, 1988     Harry Yee*                Changed message in dialogdata.asm 'Disk is locked, so any changes made to *                the Choose Printer dialog will not be saved.' to a more general message, *                'Changes made to the Choose Printer dialog could not be saved to disk.'.*                This message is put up whenever any ProDOS error is encountered during a *                _Write call to the Printer.setup file. Procedure WriteSetupFile changed*                to not check for just 'Disk Locked' and 'Invalid Ref Num' errors. Any error*                encountered will now put up an alert box.**                Routine WriteSetupFile now checks for VolumeNotFound and FileNotFound errors*                encountered during _Open. Insert disk message appears for VolumeNotFound *                error and for FileNotFound, a file is created if disk is unlocked and *                the appropriate selections are then saved to printer.setup. This fixes the*                problem you get when, 1) there is no printer.setup file present already when *                PMStartup is called, 2) the disk is locked which ensures that the *                Printer.setup does not get created, 3) then you bring up Choose Printer*                4) eject the system disk and then un-write protect it, insert the disk back*                and click the 'OK' button, in the past the dialog 'Changes made to the *                Choose Printer dialog could not be saved to disk.' would appear whether*                or not the disk was locked, now a printer.setup file is created and the*                changes are then recorded.** Version 2.2d2  July 25, 1988      Harry Yee	(for System Disk 4.0d14)*                Put change in routine DefaultSetup. In past the direct connect screen would*                always come up no matter what (i.e. if all the port drivers were missing*                except for the AppleTalk port driver then the direct connect screen would*                still come up). Now if AppleTalk is the only port driver found then the *                AppleTalk screen comes up. This same change was also put in PrChooser.asm.**                July 26, 1988      Harry Yee	*                In routine ReadSetupFile, I now make the call _Get_EOF. If the length of*                the Printer.Setup file is not #EndSetupFileInfo-SetupFileInfo then I assume*                that Printer.Setup file is an old printer.setup file or a corrupted one. *                The current Printer.Setup file is then deleted and a new one is created with*                the default settings.**                July 27, 1988      Harry Yee*                Apps. cursor was not being restored correctly when Choose Printer was*                being called.** Version 2.2d3  July 22, 1988      Harry Yee	(for System Disk 4.0d15)*                Was saving and restoring cursor in the wrong place. In routines Dispatch and *                DPort, saving and restoring of cursor was being done for every printer *                and port driver being made. This should have only been done if a driver needed*                to be loaded.** Version 2.2d4  August 3,1988      Harry Yee	(for System Disk 4.0d16)*                Once zone button was de-activated it was never activated again. BRC #34687 Fixed. **                August 8,1988      Harry Yee*                Changed GetPrNames so that it doesn't need to use any direct page. (BRC #34846)** Version 3.0 *   d1 November 29, 1988  Suki Lee*      Added dispatching code for two new calls in the drivers: PrGetPrinterSpecs and *      PrGetPgOrientation. Two new constants, oPrGetPrinterSpecs and oPrGetPgOrientation,*      are added to PrintMgr.equ for dispatching these new calls. Also added two new *      calls PMSetDocName and PMGetDocName to allow the application to set the name of*      document to be printed and the printer driver to access that information.**   d2 December 13, 1988  Suki Lee*      Replaced PrChooser.asm with code in PrintMgr.asm to put up an alert asking the *      user to use the Control Panel desk accessory to select a printer. Modified the*      Makefile to delete dependencies on PrChooser.asm. **      December 14, 1988  Suki Lee*      Added error handling routines to DummyPrinter to handle the new printer driver *      calls PrGetPrinterSpecs and PrGetPgOrientation.**      December 15, 1988  Suki Lee*      Added code in Dispatch and Dport to check current driver to see if the call is *      supported before dispatching to it. New drivers which support new calls added *      for this release (PrGetPrinterSpecs and PrGetPgOrientation for printer drivers)  *      and any subsequent new calls contains a header two words long: first word is 0  *      followed by a call count word.**      December 16, 1988  Suki Lee*      DocumentNamePtr is initialized when the driver is loaded, and then it maintains*      the value that the application or the driver sets. This poses a problem since*      the tool is not reloaded each time an application is launched. Added initialization*      of the pointer at PMStartup time.**   d3 January 16, 1989   Suki Lee*      Removed dispatch code and constants associated with the three calls that were*      removed from the AppleTalk driver: GetPrinterList, GetMyZone and GetZoneList. *      These calls are no longer needed since the Choose Printer functionality has been*      moved to the Control Panel.*      Also removed code, constants and string data associated with the Choose Printer*      dialog in this file, PrintMgr.equ and Dialogdata.asm.**      January 18, 1989   Suki Lee*      Added call to PrDevStartUp in LoadCurrentPort. This ensures that the start up code*      is called each time a new port driver is loaded. Removed routine BuildNetName since*      the PrDevStartUp call performs the same function.**      January 24, 1989   Suki Lee*      LoadCurrentPrinter and LoadCurrentPort are modified to read the current printer and *      port choices from the setup file and set up the internal data structure before *      loading, since this is now our only means of communications with the Control Panel's *      printer cDevs.**   d4 March 30, 1989     Suki Lee*      Added call to PrDevShutDown in UnloadCurrentPort to balance it with the PrDevStartUp*      call made in LoadCurrentPort.**   d5 April 3, 1989      Suki Lee*      PrDevShutDown call was placed where it gets called after the port driver has been *      unloaded, causing the driver to be loaded again. Moved call to before unloading.**      April 10, 1989     Suki Lee*      Added code in PMGetNetworkName, PMGetUserName and PMGetZoneName to check if *      AppleTalk is selected before returning a string. If direct connect, then a NIL *      pointer is returned.**   d6 May 19, 1989       Suki Lee*      Since the prChooser dialog code was taken out, the result returned was false. But*      some old apps rely on the result to be true, which meant OK was hit. Changed the*      result to return true. BRC #49224**      May 26, 1989       Suki Lee*      Modified alert strings which still refer to the Choose Printer dialog to use *      "Control Panel".**      June 1, 1989       Suki Lee*      When an error occurs during loading of a driver, an internal flag is set to -1.*      But the code which uses the flag treats -1 as if the driver had been loaded. Set*      this flag to 0 to force a reload of the driver in the event that the user changed*      the printer or port selection.******************************************************************************************************************************************************************************* Changes since first prototype release:** If the setup file	is missing from the	drivers subdirectory,* we create a default setup file.  This	has the first* printer driver in	the list and the first port driver in the* list.  The user name is John Q. Public and the network printer* name is LASERWRITER.  (Does not display insert disk msg.)** If there is an error on loading of the printer (or port )driver* at startup time, I check to see if the error is file not* found.  If it is we try the default printer (or port).  This* can happen if user deletes current driver. (Does not display* insert disk msg.)** The Prchooser and	NetChooser both use	the list manager. Program* must load list manager.** After calling PRChooser, I only reload drivers if the drivers* have changed.** Code went from over 11K to just over 5K.** (Above comments from Suki Lee, late 1988 -- Ben Koning)***************************************************************************************** BEGIN 6.0** 5-Mar-91	Dave Lyons (for 6.0d28)** Changed version number from $0300 to $8301 (in equates file).* Killed a ton of stray semicolons.  They bug me.** Adding support for Printer.Setup file being in the user's AppleShare user folder* instead of always "*/System/Drivers/Printer.Setup".** 7-Mar-91	DAL** Got around to finishing the above stuff.  If we get an error trying to do a* GetFileInfothe on the user's setup folder, then we use the "*:System:Drivers:* Printer.Setup" path.** The network path is ":xxx:Users:username:Setup:Printer.Setup"** 15-Apr-91	Ben Koning** Eliminated usage of 'all.macros'.** Changed dialog boxes that pop up from using NoteAlert and StopAlert to AlertWindow,* simplifying code and saving space.***************************************************************************************** Begin 6.0.1** 18-Nov-92	Dave Lyons (6.0.1d12)** Changed version number from $0301 to $8302.** Fixed bad-parameter error code from PMLoadDriver/PMUnloadDriver to be $1309,* as documented (was returning $1308 before).** 1-Apr-93	Steve Stephenson (6.0.1d16)** Changed version to $0302 for 6.0.1 (final)***************************************************************************************	blanks off	string asis	include 'm16.util2'	include 'm16.locator'	include 'm16.misctool'	include 'm16.memory'	include 'm16.prodos'	include 'm16.gsos'	include 'm16.loader'	include 'm16.quickdraw'	include 'm16.qdaux'	include 'm16.list'	include 'm16.window'	include 'm16.dialog'	include 'e16.dialog'	include 'PrintMgr.equ'	include 'special.macros'	;-----------------------------------------------;;   Imported addresses;;-----------------------------------------------	import OKButtonStr	import CancelButtonStr	import InsertDiskStr	;-----------------------------------------------;;   Forward addresses and entries;;-----------------------------------------------	ENTRY AppendString	ENTRY AppleTalkOn	ENTRY AppleTalkStr	ENTRY CloseID	ENTRY CloseParams	ENTRY CloseSetup	ENTRY CloseSetupID	ENTRY CloseSetupParams	ENTRY CopyString	ENTRY CreateSetupParams	ENTRY CurrentDriver	ENTRY CurrentNetName	ENTRY CurrentPort	ENTRY CurrentPrinter	ENTRY CurrentPrinter1	ENTRY CurrentPrinter2	ENTRY CurrentUser	ENTRY CurrentZoneName	ENTRY DPort	ENTRY DPortAdr	ENTRY DefaultDocName	ENTRY DefaultPort	ENTRY DefaultPrinter	ENTRY DefaultSetup	ENTRY DefaultZone	ENTRY DerefTemp1ToTemp2	ENTRY DestroyParams	ENTRY Die	ENTRY DirPath	ENTRY Dispatch	ENTRY DispatchAdr	ENTRY DisposePortList	ENTRY DisposePrinterList	ENTRY DocumentNamePtr	ENTRY DriverError	ENTRY DriverPath	ENTRY DriverSubPath	ENTRY DummyPort	ENTRY DummyPrinter	ENTRY EndSetupFileInfo	ENTRY EntryAuxType	ENTRY EntryName	ENTRY EntryType	ENTRY EqualString	ENTRY Err0	ENTRY Err10	ENTRY Err12	ENTRY Err2	ENTRY Err4	ENTRY Err4Plus	ENTRY Err8	ENTRY Err8Plus	ENTRY Exit0	ENTRY Exit2	ENTRY Exit4	ENTRY GetDirID	ENTRY GetDirParams	ENTRY GetEOFID	ENTRY GetEOFParams	ENTRY GetFileParams	ENTRY GetMem	ENTRY InitCursor	ENTRY InsertPortList	ENTRY InsertPrinterList	ENTRY IsPortThere	ENTRY Length	ENTRY ListSize	ENTRY LoadCurrentPort	ENTRY LoadCurrentPrinter2	ENTRY LoadSomething	ENTRY NoAppleTalk	ENTRY NumPorts	ENTRY NumPrinters	ENTRY OpenID	ENTRY OpenParams	ENTRY OpenSetup	ENTRY OpenSetupID	ENTRY OpenSetupParams	ENTRY PMActive	ENTRY PMBootInit	ENTRY PMLoadDriver	ENTRY PMReset	ENTRY PMShutDown	ENTRY PMStartup	ENTRY PMUnloadDriver	ENTRY PMVersion	ENTRY PathBuffer	ENTRY PmGetNetWorkName	ENTRY PmGetPortName	ENTRY PmGetPrinterName	ENTRY PmGetUserName	ENTRY PmGetZoneName	ENTRY PmInsertDisk	ENTRY PmSetNetWorkName	ENTRY PmSetPortName	ENTRY PmSetPrinterName	ENTRY PmSetUserName	ENTRY PmSetZoneName	ENTRY PmSetDocName	ENTRY PmGetDocName	ENTRY PortDriverID	ENTRY PortInMem	ENTRY PortList	ENTRY PortListSize	ENTRY PostAlert	ENTRY PrChooser	ENTRY PrinterDriverID	ENTRY PrinterInMem	ENTRY PrinterList	ENTRY PrinterListSize	ENTRY ReadSetUpFile	ENTRY ReadSetupID	ENTRY ReadSetupParams	ENTRY SetCurrentDriver	ENTRY SetCurrentPrinter	ENTRY SetupDriverLists	ENTRY SetupFileInfo	ENTRY SetupFileName	ENTRY SizeOfFile	ENTRY TheEntry	ENTRY TransferCount	ENTRY UnLoadCurrentPort	ENTRY UnLoadCurrentPrinter	ENTRY UnloadSomething	ENTRY WaitCursor	ENTRY WriteSetupFile	ENTRY WriteSetupID	ENTRY WriteSetupParams	ENTRY insertdisk	ENTRY loadCurrentPrinter	ENTRY xDevAsyncRead	ENTRY xDevClose	ENTRY xDevWriteBack	ENTRY xDevIsItSafe	ENTRY xDevOpen	ENTRY xDevPrChanged	ENTRY xDevRead	ENTRY xDevShutdown	ENTRY xDevStartup	ENTRY xDevStatus	ENTRY xDevWrite	ENTRY xGetDeviceName	ENTRY xPrCloseDoc	ENTRY xPrClosePage	ENTRY xPrControl	ENTRY xPrDrvrVer	ENTRY xPrError	ENTRY xPrJobDialog	ENTRY xPrOpenDoc	ENTRY xPrOpenPage	ENTRY xPrPicfile	ENTRY xPrPixelMap	ENTRY xPrPortVer	ENTRY xPrSetError	ENTRY xPrStlDialog	ENTRY xPrValidate	ENTRY xPrintDefault	ENTRY xPrGetPrinterSpecs	ENTRY xPrGetPgOrientation	entry BuildSetupPath	;7-Mar-91 DAL**************************************************************************************** The Call Table***************************************************************************************	EXPORT CallTableCallTable	PROCTheStart	DC.L (TheEnd-TheStart)/4	DC.L PMBootInit-1	      ; 1  $0113	DC.L PMStartup-1	      ; 2  $0213	DC.L PMShutDown-1	      ; 3  $0313	DC.L PMVersion-1	      ; 4  $0413	DC.L PMReset-1	      ; 5  $0513	DC.L PMActive-1	      ; 6  $0613	DC.L PMBootInit-1         ; 7  $0713  ; reserved	DC.L PMBootInit-1         ; 8  $0813  ; reserved	DC.L xPrintDefault-1      ; 9  $0913	DC.L xPrValidate-1	      ;10  $0A13	DC.L xPrStlDialog-1	      ;11  $0B13	DC.L xPrJobDialog-1	      ;12  $0C13	DC.L xPrPixelMap-1	      ;13  $0D13	DC.L xPrOpenDoc-1	      ;14  $0E13	DC.L xPrCloseDoc-1	      ;15  $0F13	DC.L xPrOpenPage-1	      ;16  $1013	DC.L xPrClosePage-1	      ;17  $1113	DC.L xPrPicfile-1	      ;18  $1213	DC.L xPrControl-1	      ;19  $1313	DC.L xPrError-1	      ;20  $1413	DC.L xPrSetError-1	      ;21  $1513	DC.L PrChooser-1	      ;22  $1613	DC.L xGetDeviceName-1     ;23  $1713	DC.L xPrGetPrinterSpecs-1 ;24  $1813	DC.L xDevPrChanged-1      ;25  $1913	DC.L xDevStartup-1	      ;26  $1A13	DC.L xDevShutdown-1	      ;27  $1B13	DC.L xDevOpen-1	      ;28  $1C13	DC.L xDevRead-1	      ;29  $1D13	DC.L xDevWrite-1	      ;30  $1E13	DC.L xDevClose-1	      ;31  $1F13	DC.L xDevStatus-1	      ;32  $2013	DC.L xDevAsyncRead-1      ;33  $2113	DC.L xDevWriteBack-1      ;34  $2213	DC.L xPrDrvrVer-1	      ;35  $2313	DC.L xPrPortVer-1	      ;36  $2413		DC.L PMGetZoneName-1      ;37  $2513 	DC.L PMSetZoneName-1      ;38  $2613	DC.L PMInsertDisk-1	      ;39  $2713	DC.L PMGetPrinterName-1   ;40  $2813	DC.L PMGetPortName-1      ;41  $2913	DC.L PMGetUserName-1      ;42  $2A13	DC.L PMGetNetWorkName-1   ;43  $2B13	DC.L PMSetPrinterName-1   ;44  $2C13	DC.L PMSetPortName-1      ;45  $2D13	DC.L PMSetUserName-1      ;46  $2E13	DC.L PMSetNetWorkName-1   ;47  $2F13		DC.L xDevIsItSafe-1	      ;48  $3013	DC.L PMBootInit-1	      ;49  $3113   ; unused	DC.L PMBootInit-1	      ;50  $3213   ; unused	DC.L PMBootInit-1	      ;51  $3313   ; unused		DC.L PMUnloadDriver-1     ;52  $3413	DC.L PMLoadDriver-1	      ;53  $3513	DC.L PMGetDocName-1	      ;54  $3613	DC.L PMSetDocName-1	      ;55  $3713	DC.L xPrGetPgOrientation-1 ;56 $3813TheEnd			ENDP****************************************************************** PMBootInit & PMReset** Does nothing.******************************************************************	EXPORT PMBootInitPMBootInit	PROC	EXPORT PMResetPMReset		       	lda #0	clc	rtl	ENDP******************************************************************* PMStartup**       UserID	  word*       DirectPage	  word******************************************************************	EXPORT PMStartupPMStartup	PROC	DefineStackOrigB	BYTEOrigD	WORDRTL1	BLOCK 3RTL2	BLOCK 3DPage	WORDUID	WORD	phd	; save direct	phb	; save dbr	phk	; set dbr	plb	lda DPage,s	tcd	; switch it in	lda UID,s	sta UserId;----------------------------------------------------------;; Setup Driver lists, read setup file and load; appropriate drivers.;	pha	_ListVersion	; check if list manager is loaded or not;		; if not start it up just in case;		; someone wants to select Choose Printer	pla	bcc AllIsWell	PushWord #28	PushWord #0	_LoadOneToolAllIsWell	lda #0000	sta >PrinterDriverID ; 1= print driver loaded, 0= not loaded	sta >PortDriverID	; 1= port driver loaded, 0= not loaded	sta >NumPrinters	; number of printer	drivers found	sta >NumPorts	; number of port drivers found	sta >NoAppleTalk	; 1= AppleTalk driver found	jsl SetupDriverLists ; find all the printer/port drivers in		; the DRIVERS folder and put them in a		; list for the list	manager to use	bcs NoDriversFolder	; check if the Drivers folder was opened ok		; if not then just return w/o setting up default		; values or setting current printer etc,...	jsl ReadSetUpFile	; get either the default settings for		; the choose printer dialog or read the		; printer.setup file for saved settings.	jsr SetCurrentPrinter	jsr SetCurrentDriver;-----------------------------------------------------------;; Initialize the document name pointer to the default name of "Unknown"; for cases where the application is not setting the document name. ;	lda #DefaultDocName	sta DocumentNamePtr+0	lda #^DefaultDocName	sta DocumentNamePtr+2	;----------------------------------------------------------;; Set our WAP entry!;NoDriversFolder	pushword #$00	; system tool	Pushword #Toolnum	; this tool	pushword #0	; high word is zero	phd	; low word is d-reg	_SetWap;----------------------------------------------------------;; We're done:  clean up stack, and quit.;	lda #$0000	plb	pld	brl Exit4	ENDP******************************************************************* PMShutDown** Shuts tool down.******************************************************************	EXPORT PMShutDownPMShutDown	PROC	phd	tcd	phb	phk	plb	jsr DisposePrinterList	jsr DisposePortList	jsr UnLoadCurrentPrinter	jsr UnLoadCurrentPort;----------------------------------------------------------;; Clear the WAP;	pushword #$00	; system tool	Pushword #Toolnum	; this tool	PushLong #0	_SetWap	lda #$0000	plb	pld	brl Exit0	ENDP******************************************************************* PMActive** Returns whether or not the print manager is active.******************************************************************	EXPORT PMActivePMActive	PROC	DefineStackRTL1	block 3RTL2	block 3ActiveResult	word	cmp #0	bne AmActive	EXPORT FinishActiveFinishActive	sta ActiveResult,s	lda #0	clc	rtlAmActive	lda #True	bra FinishActive	ENDP******************************************************************* PMVersion** Returns version number******************************************************************	EXPORT PMVersionPMVersion	PROC	lda #VersionNb	bra FinishActive	ENDP******************************************************************* PMInsertDisk** Routine that is used put up mount volume message.  This is an* entry point so that the drivers can use the code in the main* tool.******************************************************************	EXPORT PmInsertDiskPmInsertDisk	PROC	phd	phb	phk	plb	jsr insertdisk	plb	pld	lda #0	brl exit0	ENDP******************************************************************* PMGetPrinterName* PMGetPortName* PMGetUserName* PMGetNetworkName** Returns a pointer	to the current name	on the stack******************************************************************	EXPORT PmGetPrinterNamePmGetPrinterName	PROC	jsr SetCurrentPrinter	lda #CurrentPrinter	ldx #^CurrentPrinter	bra SetPtr	EXPORT PMGetPortNamePMGetPortName	jsr SetCurrentDriver	lda #CurrentDriver	ldx #^CurrentDriver	bra SetPtr	EXPORT PMGetUserNamePMGetUserName	lda >AppleTalkOn	; if user selected direct connect, the 	beq DirConnect	; name in the variable is not valid	lda #CurrentUser	ldx #^CurrentUser	bra SetPtr	EXPORT PMGetNetWorkNamePMGetNetWorkName	lda >AppleTalkOn	; if user selected direct connect, the 	beq DirConnect	; name in the variable is not valid	lda #CurrentNetName	ldx #^CurrentNetName	bra SetPtr	EXPORT PMGetZoneNamePMGetZoneName	lda >AppleTalkOn	; if user selected direct connect, the 	beq DirConnect	; name in the variable is not valid	lda #CurrentZoneName	ldx #^CurrentZoneName	bra SetPtr	DirConnect	lda #0	taxSetPtr	DEFINESTACKRTL1	block 3rtl2	block 3PtrResult	LONG	sta PtrResult,s	txa	sta PtrResult+2,s	lda #$0000	brl Exit0	ENDP******************************************************************* PMSetPrinterName* PMSetPortName* PMSetUserName* PMSetNetName**      PtrToNewName******************************************************************	EXPORT PmSetPrinterNamePmSetPrinterName	PROC	jsr SetCurrentPrinter	ldx #CurrentPrinter	; printer setting for appletalk	ldy #^CurrentPrinter	bra SetName	EXPORT PMSetPortNamePMSetPortName	jsr SetCurrentDriver	ldx #CurrentPort	ldy #^CurrentPort	bra SetName	EXPORT PMSetUserNamePMSetUserName	ldx #CurrentUser	ldy #^CurrentUser	bra SetName	EXPORT PMSetNetWorkNamePMSetNetWorkName	ldx #CurrentNetName	ldy #^CurrentNetName	bra SetName	EXPORT PMSetZoneNamePMSetZoneName	ldx #CurrentZoneName	ldy #^CurrentZoneNameSetName	DEFINESTACKOrigB	BYTEOrigD	WORDRTL1	block 3rtl2	block 3NamePtr	LONG	phd	; save d	tcd	; set direct page to ours	phb	; save dbr	phk	; set dbr to k	plb	jsl ReadSetupFile	; read the setup file	lda NamePtr,s	sta Temp1	lda NamePtr+2,s	sta Temp1+2	stx Temp2	sty Temp2+2	lda [Temp1]	and #$00FF	tay	dey	sep #%00100000	longa offNameLoop	lda [Temp1],y	sta [Temp2],y	dey	bpl NameLoop	rep #%00100000	longa on	jsl WriteSetupFile	; write it back out	plb	; clean up and quit.	pld	lda #$0000	brl Exit4	ENDP******************************************************************* PMLoadDriver** This routine accepts as input a word value;*   0 - load both the current printer and port driver*   1 - load the current printer driver	only*   2 - load the current port driver only** The result is also a word value which	tells the caller whether the call was* successful or not.** If result was False then error was invalid parameter passed, else it is just* the result of loader call _InitialLoad******************************************************************	EXPORT PMLoadDriverPMLoadDriver	PROC	DEFINESTACKOrigB	BYTEOrigD	WORDRTL1	block 3RTL2	block 3LoadWhat	WORD	phd	; save d	tcd	; set direct page to ours	phb	; save dbr	phk	; set dbr to k	plb	stz loadError		lda LoadWhat,s	; what drivers do we unload	bmi InvalidParam1	; negative number, not valid choice	cmp #3	bge InvalidParam1	; 3 or greater are not valid either	cmp #2	; is it the port driver only?	beq doPortDrvr	; yes		lda >PrinterDriverID ; 0 or 1 indicates that printer driver should be loaded	bne Xit1	; check if anything is loaded	jsr LoadCurrentPrinter2	sta LoadError		lda LoadWhat,s	; is it both drivers?	beq doPortdrvr	; yes, go do port also		lda loadError	; Pass error, if any, back to caller	bra ErrorExit	doPortdrvr		; load the port driver	lda >PortDriverID	; if not loaded already	bne Xit1	jsr LoadCurrentPort	bcs ErrorExit	; Error from this load	lda LoadError	; Error from loading printer driver, if any	bra ErrorExit	Xit1	lda #0ErrorExit	plb	pld	brl Exit2InvalidParam1		;	lda #BadParam	; if bad param. set	result to False	bra ErrorExit	; go there instead of Xit1 (BK 11/7/89)loadError	DS.B 2	ENDP******************************************************************* PMUnloadDriver** This routine accepts as input a word value;*   0 - unload both	the current printer	and port driver*   1 - unload the current printer driver only*   2 - unload the current port driver only** The result is also a word value which	tells the caller whether the call was* successful or not.** If result was False then error was invalid parameter passed, else it is just* the result of loader call _UserShutDown******************************************************************	EXPORT PMUnloadDriverPMUnloadDriver	PROC	DefineStackOrigB	BYTEOrigD	WORDRTL1	block 3RTL2	block 3UnloadWhat	WORD	phd	; save d	tcd	; set direct page to ours	phb	; save dbr	phk	; set dbr to k	plb	lda UnloadWhat,s	; what drivers do we unload	bmi InvalidParam2	; negative number, not valid choice	cmp #3	bge InvalidParam2	; 3 or greater are not valid either	cmp #2	; is it the port driver only?	beq DoPort		jsr UnloadCurrentPrinter	sta UnloadError		lda UnloadWhat,s	; is it both drivers?	beq DoPort	; yes, go do port	lda UnloadError	bra Xit2	DoPort	jsr unloadCurrentPort	bcs Xit2	; Error from this unload	lda UnLoadError	; Error from unloading printer driver, if anyXit2	plb	pld	brl Exit2InvalidParam2	lda #BadParam	; if bad param. set	result to False	bra Xit2UnloadError	DS.B 2	ENDP******************************************************************* PMSetDocName** input: ptr to name string (pString)* output: none******************************************************************	EXPORT PMSetDocNamePMSetDocName	PROC	DefineStackOrigB	BYTEOrigD	WORDRTL1	block 3RTL2	block 3DocNamePtr	LONG	phd	; save d	tcd	; set direct page to ours	phb	; save dbr	phk	; set dbr to k	plb		lda DocNamePtr,s	; get the name pointer off the stack	sta DocumentNamePtr	; stores it locally		lda DocNamePtr+2,s	; same for bank addr	sta DocumentNamePtr+2 	lda #0		plb	pld	brl Exit4	ENDP******************************************************************* PMGetDocName** input: result space * output: ptr to name string (pString)******************************************************************	EXPORT PMGetDocNamePMGetDocName	PROC	DefineStackOrigB	BYTEOrigD	WORDRTL1	block 3RTL2	block 3DocNamePtr	LONG	phd	; save d	tcd	; set direct page to ours	phb	; save dbr	phk	; set dbr to k	plb		lda DocumentNamePtr	; get the name pointer 	sta DocNamePtr,s	; return it on the stack as result		lda DocumentNamePtr+2 ; same for bank addr	sta DocNamePtr+2,s		lda #0		plb	pld	brl Exit0	ENDP	****************************************************************** PrChooser**     ResultCode** Displays dialog directing user to the control panel chooser.* Always returns true.*****************************************************************	EXPORT PrChooserPrChooser	PROC	definestackOrigB	byteOrigD	wordRTL1	block 3RTL2	block 3Result	word	phd		;set up environment	tcd	phb	phk	plb		lda #True		;return true since OK hit,	sta result,s		;some apps depend on this being true		pha		;pass result space	pushword #%000		;pass reference is ptr to cstring	pushlong #0		;pass no substitution array	import UseCtrlPanelMesg	;pass ptr to alert box def string	pushlong #UseCtrlPanelMesg	_AlertWindow	pla		;get button that was hit and ignore		lda #0		;return no error		plb		;restore environment and exit	pld	brl Exit0	ENDP	******************************************************************* Calls passed on to drivers!******************************************************************	EXPORT PassPass	PROC;----------------------------------------------------------;; These calls are passed on to the current printer driver.;	EXPORT xPrintDefaultxPrintDefault	ldx #oPrintDefault	jmp Dispatch		EXPORT xPrValidatexPrValidate	ldx #oPrValidate	jmp Dispatch		EXPORT xPrStlDialogxPrStlDialog	ldx #oPrStlDialog	jmp Dispatch		EXPORT xPrJobDialogxPrJobDialog	ldx #oPrJobDialog	jmp Dispatch		EXPORT xPrDrvrVerxPrDrvrVer	ldx #oPrDrvrVer	jmp Dispatch		EXPORT xPrOpenDocxPrOpenDoc	ldx #oPrOpenDoc	jmp Dispatch		EXPORT xPrCloseDocxPrCloseDoc	ldx #oPrCloseDoc	jmp Dispatch		EXPORT xPrOpenPagexPrOpenPage	ldx #oPrOpenPage	jmp Dispatch		EXPORT xPrClosePagexPrClosePage	ldx #oPrClosePage	jmp Dispatch		EXPORT xPrPicfilexPrPicfile	ldx #oPrPicfile	jmp Dispatch		EXPORT xPrControlxPrControl	ldx #oPrControl	jmp Dispatch		EXPORT xPrErrorxPrError	ldx #oPrError	jmp Dispatch		EXPORT xPrSetErrorxPrSetError	ldx #oPrSetError	jmp Dispatch		EXPORT xGetDeviceNamexGetDeviceName	ldx #oGetDeviceName	jmp Dispatch		EXPORT xPrPixelMapxPrPixelMap	ldx #oPrPixelMap	jmp Dispatch	EXPORT xPrGetPrinterSpecsxPrGetPrinterSpecs	ldx #oPrGetPrinterSpecs	jmp Dispatch		EXPORT xPrGetPgOrientationxPrGetPgOrientation	ldx #oPrGetPgOrientation	jmp Dispatch	;----------------------------------------------------------;; The remaining calls are passed on to the port driver.;	EXPORT xDevPrChangedxDevPrChanged	ldx #oDevPrChanged	jmp DPort		EXPORT xDevStartupxDevStartup	ldx #oDevStartup	jmp DPort		EXPORT xDevShutdownxDevShutdown	ldx #oDevShutdown	jmp DPort		EXPORT xDevOpenxDevOpen	ldx #oDevOpen	jmp DPort	EXPORT xDevReadxDevRead	ldx #oDevRead	jmp DPort		EXPORT xDevWritexDevWrite	ldx #oDevWrite	jmp DPort		EXPORT xDevClosexDevClose	ldx #oDevClose	jmp DPort		EXPORT xDevStatusxDevStatus	ldx #oDevStatus	jmp DPort		EXPORT xDevAsyncReadxDevAsyncRead	ldx #oDevAsyncRead	jmp DPort		EXPORT xDevWriteBackxDevWriteBack	ldx #oDevWriteBack	jmp DPort		EXPORT xPrPortVerxPrPortVer	ldx #oPrPortVer	jmp DPort		EXPORT xDevIsItSafexDevIsItSafe	ldx #oDevIsItSafe	jmp DPort		ENDP******************************************************************* Dispatch** Dispatches control to the printer driver.******************************************************************	EXPORT DispatchDispatch	PROC	definestackysave	wordasave	wordbsave	bytedsave	wordrtladr	block 3	pha	; get 3 bytes on stack	phb	phd	; save d	tcd	; get ours		phb	; switch d	phk	plb	stx CallDispNum	; save x, we need it		pha	; save a-reg	phy	; save y-reg	lda >PrinterDriverID	bne NoPrinterChg	pha 	pha 	_GetCursorAdr	; save current cursor		jsr WaitCursor		jsr loadCurrentPrinter		_SetCursor	; restore original cursorNoPrinterChg	lda >DispatchAdr+2	sta Temp1+2	lda >DispatchAdr	sta Temp1		lda [Temp1]	; set up a flag to indicate old or new driver	and #$00FF	; only check first byte	sta IsOldDriver	; 0 is new driver, nonzero is old driver		lda CallDispNum	cmp #oPrGetPrinterSpecs	blt OldCalls		lda IsOldDriver	bne CallNotSupp		ldy #2	; check the call count	lda [Temp1],y	dec a	; subtract 1 since the index begins with 0	asl a	asl a	; 4 bytes per address entry from jump table	cmp CallDispNum	blt CallNotSupp		bra GoDispatchNew	OldCalls		lda IsOldDriver	bne GoDispatch	; for old drivers, dispatch address is all set up	GoDispatchNew	lda Temp1	clc	adc #4	; new drivers has jmp table 4 bytes from start	sta Temp1	bra GoDispatchCallNotSupp		lda #DummyPrinter	sta Temp1	lda #^DummyPrinter	sta Temp1+2		lda #CallNotSupported	sta >DriverError;-----------------------------------------------------------;; GoDispatch	lda Temp1+1	sta rtladr+1,s	lda Temp1	dec a	sta rtladr,s	ldx CallDispNum	; restore x		ply	; get y back	pla	; get a back	plb	; get data bank back	pld	; get direct page back		rtl	; dispatch	EXPORT IsOldDriverIsOldDriver	DS.B 2	EXPORT CallDispNumCallDispNum	DS.B 2	ENDP******************************************************************* DPort** Dispatches control to the port driver.******************************************************************	EXPORT DPortDPort	PROC	definestackysave	wordasave	wordbsave	bytedsave	wordrtladr	block 3	pha	; get 3 bytes on stack	phb	phd	; save d	tcd	; get ours		phb	; switch d	phk	plb	stx CallDispNum	; save x, we need it		pha	; save a-reg	phy	; save y-reg	lda >PortDriverID	bne NoPortChange	pha	; save current cursor	pha	_GetCursorAdr		jsr WaitCursor		lda CallDispNum	pha	; save it since LoadCurrentPort will trash this value		jsr LoadCurrentPort		pla	sta CallDispNum	; restore it		_SetCursorNoPortChange		lda >DPortAdr+2	sta Temp1+2	lda >DPortAdr	sta Temp1		lda [Temp1]	; set up a flag to indicate old or new driver	and #$00FF	; only check first byte	sta IsOldDriver	; 0 is new driver, nonzero is old driver		lda CallDispNum	cmp #oNextNewPortCall	blt OldCalls		lda IsOldDriver	bne CallNotSupp		ldy #2	; check the call count	lda [Temp1],y	dec a	; subtract 1 since the index begins with 0	asl a	asl a	; 4 bytes per address entry from jump table	cmp CallDispNum	blt CallNotSupp		bra GoDispatchNew	OldCalls		lda IsOldDriver	bne GoDispatch	; for old drivers, dispatch address is all set up	GoDispatchNew	lda Temp1	clc	adc #4	; new drivers has jmp table 4 bytes from start	sta Temp1	bra GoDispatchCallNotSupp		lda #DummyPort	sta Temp1	lda #^DummyPort	sta Temp1+2		lda #CallNotSupported	sta >DriverError;-----------------------------------------------------------;; GoDispatch	lda Temp1+1	sta rtladr+1,s	lda Temp1	dec a	sta rtladr,s	ldx CallDispNum	; restore x		ply	; get y back	pla	; get a back	plb	; get data bank back	pld	; get direct page back		rtl	; dispatch	ENDP;                copy    Driver.asm******************************************************************** SetCurrentPrinter** A check is made to see if appletalk or direct connect is selected* and then according to that selection the proper printer is* made the CurrentPrinter.*******************************************************************	EXPORT SetCurrentPrinterSetCurrentPrinter	PROC	lda >AppleTalkOn	beq DConnectOn	PushLong #CurrentPrinter1	PushLong #CurrentPrinter	jsr CopyString	bra ATalkOnDConnectOn	PushLong #CurrentPrinter2	PushLong #CurrentPrinter	jsr CopyStringATalkOn	rts	ENDP******************************************************************** SetCurrentDriver** A check is made to see if appletalk or direct connect is selected* and then according to that selection the proper port driver* made the CurrentDriver*******************************************************************	EXPORT SetCurrentDriverSetCurrentDriver	PROC	lda >AppleTalkOn	beq NotATPort	PushLong #AppleTalkStr	PushLong #CurrentDriver	jsr CopyString	bra ATPortOnNotATPort	PushLong #CurrentPort	PushLong #CurrentDriver	jsr CopyStringATPortOn	rts	ENDP******************************************************************** LoadCurrentPrinter** Loads the current	printer driver.  Builds the path name we* want and then calls LoadSomething which returns the userid* in the a-register.  Returns address in x-reg and y-reg.*******************************************************************	EXPORT LoadCurrentPrinterLoadCurrentPrinter	PROC	jsr IsPortThere	bcs PrinterError	EXPORT LoadCurrentPrinter2LoadCurrentPrinter2	jsl ReadSetupFile		; find out what user had picked		jsr SetCurrentPrinter	; set the internal data structures accordingly	PushLong #DriverSubPath	PushLong #PathBuffer	jsr CopyString	PushLong #PathBuffer	PushLong #CurrentPrinter	jsr AppendString	jsr LoadSomething	bcs PrinterError	sta >PrinterDriverID	txa	sta >DispatchAdr	tya	sta >DispatchAdr+2	PushLong #CurrentPrinter	PushLong #PrinterInMem	jsr CopyString	lda #0	clc	rtsPrinterError	tax		lda #0	sta >PrinterDriverID	lda #DummyPrinter	sta DispatchAdr	lda #^DummyPrinter	sta DispatchAdr+2	lda #MissingDriver	sta DriverError	txa	rts	ENDP******************************************************************** LoadCurrentPort** Loads the current	port driver.  Builds the path name we* want and then calls LoadSomething which returns the userid* in the a-register.  Returns address in x-reg and y-reg.*******************************************************************	EXPORT LoadCurrentPortLoadCurrentPort	PROC	jsl ReadSetupFile	; find out what user had picked		jsr SetCurrentDriver ; set the internal data structures accordingly	PushLong #DriverSubPath	PushLong #PathBuffer	jsr CopyString	PushLong #PathBuffer	PushLong #CurrentDriver	jsr AppendString	jsr LoadSomething	bcs PortError	sta >PortDriverID	txa	sta >DPortAdr	tya	sta >DPortAdr+2	PushLong #CurrentDriver	PushLong #PortInMem	jsr CopyString;-----------------------------------------------------------;; Added January 17, 1989 to ensure that PrDevStartUp is called each time a port; driver is loaded .;	_GetDeviceName	PushLong #CurrentNetName	PushLong #CurrentZoneName	_PrDevStartup	lda #0	clc	rtsPortError	tax		lda #0	sta >PortDriverID	lda #DummyPort	sta DPortAdr	lda #^DummyPort	sta DPortAdr+2	txa	rts	ENDP******************************************************************** LoadSomething** Loads the driver who's path name is in the path buffer* Returns the UserID in a-reg and address of what was loaded* in x-reg and y-reg.*******************************************************************	EXPORT LoadSomethingLoadSomething	PROC	_GetFileInfo FIParams	bcs CheckForVol	PushWord #0	; dir/page stack size	PushWord #0	; dir/page stack loc	PushLong #0	; starting address	PushWord #0	; UserID assigned.	PushWord #0	; UserID to use (for now let loader;		; assign one.	PushLong #PathBuffer ; pointer to path	PushWord #0	; Not Special memory flag	_initialLoad	bcs ErrorOnLoad	pla	; get userid in a-reg	plx	; adr in x and y	ply	sta 3,s	; overstore the last piece of	pla	; useless info and get	pla	; user id back	rts	; carry is clear when get hereErrorOnLoad	plx	; remove space for id	plx	; remove space for addr	plx	plx	; remove directpage	loc	plx	; remove direct page sizeCheckForVol	cmp #VolumeNotFound	bne NotMissingDisk	jsr InsertDisk	bcc LoadSomethingNotMissingDisk	sec	rtsFIParams	DC.L FIPath	DS.B $30FIPath	str '*/'	ENDP******************************************************************** UnloadCurrentPrinter*******************************************************************	EXPORT UnLoadCurrentPrinterUnLoadCurrentPrinter PROC	lda >PrinterDriverID	beq NoDriverLoaded	jsr UnloadSomething	bcc PrDriverUnloaded	tax	; save result of _initialLoad call	lda #DummyPrinter	sta DispatchAdr	lda #^DummyPrinter	sta DispatchAdr+2	lda #MissingDriver	sta DriverError	lda #0	sta >PrinterDriverID	txa	; restore result of	loader call	bra NoDriverLoadedPrDriverUnloaded	lda #0	sta >PrinterDriverID	sta >PrinterInMemNoDriverLoaded	rts	ENDP******************************************************************** UnloadCurrentPort*******************************************************************	EXPORT UnLoadCurrentPortUnLoadCurrentPort	PROC	lda >PortDriverID	beq NoPortLoaded	pha	; save A		_PrDevShutDown	; shutdown port driver		pla	; get A back	jsr UnloadSomething	bcc PortUnloaded	tax	; save result of _userShutDown call	lda #DummyPort	sta DPortAdr	lda #^DummyPort	sta DPortAdr+2	lda #0	sta >PortDriverID	txa	; restore result of	loader call	rtsPortUnloaded	lda #0	sta >PortDriverID	sta >PortInMem	NoPortLoaded	rts	ENDP******************************************************************** UnloadSomething** Input: userID in A*******************************************************************	EXPORT UnloadSomethingUnloadSomething	PROC		PushWord #0	pha	PushWord #0	_userShutdown	plx		rts	ENDP******************************************************************** DriverChanges** Return carry set if the Current driver string is not equal* to the driver in memory string.*******************************************************************	EXPORT DriverChangesDriverChanges	PROC	EXPORT DidPrinterChangeDidPrinterChange		       	PushLong #CurrentPrinter	PushLong #PrinterInMem	jsr EqualString	beq same	sec	rtsSame	clc	rts	EXPORT DidPortChangeDidPortChange		       	PushLong #CurrentDriver	PushLong #PortInMem	jsr EqualString	beq Same	sec		rts	ENDP******************************************************************** IsPortThere** This proc checks to make sure that when any printer driver is loaded* there is corresponding port driver that has been selected and in the* 'Drivers' folder.*******************************************************************	EXPORT IsPortThereIsPortThere	PROC	lda >AppleTalkOn	beq CheckDCDriver	lda >NoAppleTalk	beq OutAndSet	bra EveryThingOKCheckDCDriver	lda CurrentDriver	and #$00FF	; check length byte, if zero then driver not there	beq OutAndSet	; HY 7/27/88	lda NumPorts	; check if there were any ports found 	beq OutAndSet	; if not then we don't need to check any further		PushLong #DriverSubPath	PushLong #DriverPath	jsr CopyString	PushLong #DriverPath	PushLong #CurrentDriver 	jsr AppendString	_GetFileInfo GetFileParams	cmp #FileNotFound	beq OutAndSetEveryThingOK	lda #0	clc	rtsOutAndSet	sec	rts	ENDP******************************************************************** ReadSetupFile** Reads the setup file if there is one.	 If there is not a setup* file it creates one and sets up some default printer configuration.* If the number of bytes to read in does not equal the number of bytes actually* read the printer.setup file file format is not compatible	with this version* of the print manager. Delete the old printer.setup file and create a new one* with the correct format and using the	default values.*******************************************************************	EXPORT ReadSetupFileReadSetupFile	PROCCreateNewSetup	jsr OpenSetup	_READ ReadSetupParams	bcs ReadOK	_Get_EOF GetEOFParams	lda SizeOfFile	cmp #EndSetupFileInfo-SetupFileInfo	beq ReadOK	jsr CloseSetup	_DESTROY DestroyParams	bra CreateNewSetupReadOK	jsr CloseSetup	rtl	ENDP******************************************************************** WriteSetupFile** Writes the setup file information back out to the system disk.*******************************************************************	EXPORT WriteSetupFileWriteSetupFile	PROC	_OPEN OpenSetupParams	bcs GotError	lda OpenSetupID	sta ReadSetupID	sta WriteSetupID	sta CloseSetupIDDoWrite	_WRITE WriteSetupParams	bcc NoErrDoAlert	PushWord #1	; show message #1 (printer.setup write error)	jsl PostAlert	plaNoErr	jsr CloseSetup	rtlGotError	cmp #FileNotFound	; do we need to create a printer.setup file?	beq CreateNewFile		cmp #VolumeNotFound	; if volume not found then put up 'Insert disk...'	beq PutUpInsertDLog	; message	bra DoAlert	CreateNewFile	_Create CreateSetupParams ; create new file, if error then put up	bcs DoAlert	; alert saying no changes could be saved.			bra WriteSetupFile	; else open new file and write out the changes.	PutUpInsertDLog	jsr InsertDisk	bcc WriteSetupFile	bcs DoAlert		ENDP******************************************************************** OpenSetup** Opens the setup file on system disk for reading or writing.*******************************************************************	EXPORT OpenSetupOpenSetup	PROC	jsr BuildSetupPath		;7-Mar-91 DAL	_OPEN OpenSetupParams	bcs Error	lda OpenSetupID	sta ReadSetupID	sta WriteSetupID	sta CloseSetupID	sta GetEOFID	rtsError	cmp #FileNotFound	beq MakeFile	cmp #VolumeNotFound	beq InsertSkipThis	jsr DefaultSetup	clc	rts;----------------------------------------------------------;; When I make a file I create it and then write the; default info into	it.;MakeFile	_Create CreateSetupParams	bcs SkipThis	jsr DefaultSetup	jsl WriteSetupFile	bra OpenSetup;----------------------------------------------------------;; Here I ask for disk insertion.  If user presses cancel; we skip this which gives us the default setup and; then quits.Insert	jsr InsertDisk	bcc OpenSetup	bcs SkipThis	ENDP******************************************************************** BuildSetupPath (7-Mar-91 DAL)** Computes either a network pathname or a local pathname for* the Printer.Setup file.** Result is a Pascal string in SetupFileName.*******************************************************************BuildSetupPath	proc	jsr BuildNetSetupPath	bcc @ok	pushlong #LocalPathname	pushlong #SetupFileName	pushlong #LocalPathEnd-LocalPathname	_BlockMove	@ok	rtsLocalPathname	str '*:System:Drivers:Printer.Setup'LocalPathEnd******************************************************************** BuildNetSetupPath (5-Mar-91 DAL)** Builds the pathname of the user's setup folder on the AppleShare* user volume, if possible.** Returns SEC if they didn't boot over AppleShare*         CLC if they booted from AppleShare*             NetUserPath = class one path of the uesr's network*                           Printer.Setup file*******************************************************************BuildNetSetupPath	import GetBootFileSystem	jsr GetBootFileSystem	cmp #$000D		;is it AppleShare?	bne @notAppleShare	_FSTSpecific gup_pblk	;get ptr to user path	bcs @notAppleShare		;no user volume, or whatever*** the returned pointer is to a class-one string with colon separators*** and no trailing colon	pushlong gup_pblk+6		;source	pushlong #NetUserPath	pushlong #128		;yeah, I'm lazy	_BlockMove*** Make sure the directory exists!	_GetFileInfoGS gfi_parms	bcs @notAppleShare		;user folder doesn't exist*** append ":Setup:Printer.Setup" to the end of the pathname	ldx #0	ldy NetUserPath		;length word@append	lda theFilename,x	sta NetUserPath+2,y	iny	inx	cpx #theFilenameLength-1	bcc @append	clc	lda NetUserPath	adc #theFilenameLength	xba		;swap length word for Pascal string	sta NetUserPath	clc	rts@notAppleShare	sec	rts;; String to append to the GetUserPath result to make a full pathname;theFilename	dc.b ':Setup:Printer.Setup'theFilenameLength	equ *-theFilename;; parameter block to get user path from appleshare.;gup_pblk	dc.w 3	;3 parameters	dc.w $000D	;id of the appleshare fst	dc.w 8	;command for get user path	dc.l NetUserPath	;ptr to pathnamegfi_parms	dc.w 2	;minimum parameter count for GetFileInfo	dc.l NetUserPath	dc.w 0	;result: access wordNetUserPath	ds.b 1	;NetUserPath is a GS/OS string	export SetupFileNameSetupFileName	ds.b 128	;SetupFileName is a Pascal string	EndP******************************************************************** GetBootFileSystem (5-Mar-91 DAL)** Output:  $000D if the boot FST is AppleShare*******************************************************************GetBootFileSystem	proc	_DInfoGS infoParms	;get the device name for the boot device	bcs oops	_VolumeGS volParms	;now do a Volume call to get the ID of the boot FST	bcs oops	lda fst_id	;get the ID number of the boot FST	rtsoops	lda #0	rtsinfoParms	dc.w 2	;pCount	dc.w 1	;device number (boot device is ALWAYS device 1)	dc.l devName	;pointer to result buffer for device namedevName	dc.w 36	;buffer lengthdevName2	dc.w 0	;string length	ds.b 32	;buffer for device namevolParms	dc.w 5	;pCount	dc.l devName2	;pointer to device name	dc.l volname	;pointer to volume name buffer	dc.l 0	;total blocks	dc.l 0	;free blocksfst_id	dc.w 0	;FST ID numbervolname	dc.w 36	;buffer lengthvolname2	dc.w 0	;string length	ds.b 32	;string buffer	EndP******************************************************************** CloseSetup** Closes the setup file that was opened	earlier.*******************************************************************	EXPORT CloseSetupCloseSetup	PROC	_CLOSE CloseSetupParams	rts	ENDP******************************************************************** DefaultSetup** This routine sets	up default SetupFile info for the case* where there is no	SetupFile to read or the disk is not around.** There are four things to setup:**     CurrentPrinter*     CurrentDriver	(Port)*     CurrentUser (name)*     CurrentNetName** Important:  This must be called after	the driver lists are* created.*******************************************************************	EXPORT DefaultSetupDefaultSetup	PROC	jsr DefaultPrinter	jsr DefaultPort	lda #0	; set the default screen to be	sta AppleTalkOn	; direct connect	lda NumPorts	; were there any port drivers found other 	bne SomeFound	; than AppleTalk	lda NoAppleTalk	; is the appletalk driver present	beq SomeFound	inc AppleTalkOn	; make the appletalk screen come up since there		; were no other port drivers found	SomeFound	sep #$30	longa off	longi off	ldx DefaultUserLoop3	lda DefaultUser,x	sta CurrentUser,x	dex	bpl Loop3	ldx DefaultNetNameLoop4	lda DefaultNetName,x	sta CurrentNetName,x	dex	bpl Loop4	ldx DefaultZoneNameLoop5	lda DefaultZoneName,x	sta CurrentZoneName,x	dex	bpl Loop5	rep #$30	longa on	longi on	rtsDefaultUser	str 'John Q. Public'DefaultNetName	str 'LASERWRITER'DefaultZoneName	str '*'	ENDP******************************************************************** DefaultPrinter** Puts the first printer in the printer	list into* CurrentPrinter.*******************************************************************	EXPORT DefaultPrinterDefaultPrinter	PROC	lda >NumPrinters	beq EmptyPrinterList		movelong PrinterList,Temp1	jsr DerefTemp1ToTemp2	clc	lda Temp2	adc #5	; 5 for list mgr	sta Temp2	bcc NoCarry1	inc Temp2+2NoCarry1	sep #$30	longa off	longi off	lda [Temp2]	tayLoop1	lda [Temp2],y	sta CurrentPrinter1,y ; first printer type in list is default	sta CurrentPrinter2,y ; for AT and DC selections	dey	bpl Loop1	rep #$30	longa on	longi on	rtsEmptyPrinterList	lda #0	sta CurrentPrinter1	sta CurrentPrinter2	 	rts		ENDP******************************************************************** DefaultPort** Puts the first Port in the port list into* CurrentDriver*******************************************************************	EXPORT DefaultPortDefaultPort	PROC	lda >NumPorts	beq EmptyPortList		movelong PortList,Temp1	jsr DerefTemp1ToTemp2	clc	lda Temp2	adc #5	; 5 for list mgr	sta Temp2	bcc NoCarry2	inc Temp2+2NoCarry2	sep #$30	longa off	longi off	lda [Temp2]	tayLoop2	lda [Temp2],y	sta CurrentPort,y	dey	bpl Loop2	rep #$30	longa on	longi on	rtsEmptyPortList	lda #0	sta CurrentPort		rts		ENDP******************************************************************** PostAlert (Message:word)** Puts up alert box	for what ever error	has occurred that needs to* be brought to the	user's attention.  This routine uses the arrow* cursor during its operation but restores the previous cursor upon* exit.  The input parameter "Message" chooses which alert box* definition string to use.*******************************************************************	EXPORT PostAlertPostAlert	PROC		defineStackOrigCursor	longOrigB	byteOrigD	wordRTLAdr	block 3Message	word		phd	;setup environment	phb	phk	plb		pha	;save original cursor address on stack	pha	_GetCursorAdr		jsr InitCursor	;set cursor to arrow		pha	;pass result space for AlertWindow call	pushword #%000	;pass reference is ptr to cstring for AlertWindow call	pushlong #0	;pass no substitution array for AlertWindow call	PMPtr	lda Message,s	;pass an alert box def string for AlertWindow call	dea	bne PMPtrItsMesg2	import SetupWriteErrMesgPMPtrItsMesg1	pushlong #SetupWriteErrMesg	bra DonePMPtr	import CantFindDrvrMesgPMPtrItsMesg2	pushlong #CantFindDrvrMesgDonePMPtr	_AlertWindow	pla	;get button that was hit and ignore		_SetCursor	;restore cursor address from stack		plb	;restore environment and exit	pld	rtl		ENDP******************************************************************* SetupDriverLists** Makes the ProDOS call GetDirEntry and	finds all the port and printer* drivers in the */system/drivers folder.  The values NumPrinters and* NumPorts are incremented respectively	each time a driver is found.** When a driver is found it is either put into the PrinterList or PortList* to be used later by the list manager for displaying in the Choose Printer* dialog.******************************************************************	EXPORT SetUpDriverListsSetUpDriverLists	PROC	stz PrinterListSize	stz PortListSize	lda #ListEntrySize*10 ; enough for 10 entries	jsr GetMem	bcc NoErr0	brl ErrorNoErr0	sta PrinterList	stx PrinterList+2	lda #ListEntrySize*10 ; enough for 10 entries	jsr GetMem	bcc NoErr1	brl ErrorNoErr1	sta PortList	stx PortList+2OpenAgain	_Open OpenParams	bcc OpenOK	brl ErrorOpenOK	lda OpenID	sta GetDirID	sta CloseIDNextEntry	_Get_Dir_Entry GetDirParams	bcs Done	lda Length	xba	sta Length	lda EntryName	; is this a real entry?	and #$00FF	beq NextEntry	lda EntryType	; is this a driver file?	and #$00FF	cmp #$00BB	bne NextEntry	lda EntryAuxType	cmp #$0001	; is it a printer driver?	bne NotPrinter	inc NumPrinters	jsl InsertPrinterList	bra NextEntryNotPrinter	cmp #$0002	; is it a port driver?	bne NotPortDrvr	inc NumPorts	jsl InsertPortList	bra NextEntryNotPortDrvr	cmp #$0003	; is it the AppleTalk Driver?	bne NextEntry	inc NoAppleTalk	PushLong #EntryName	PushLong #AppleTalkStr	jsr CopyString	bra NextEntryDone	_Close CloseParams	lda #0	clc	rtlError	pha	; save error returned on stack	jsr DisposePrinterList	jsr DisposePortList	pla	; get error back from stack	sec	rtl	ENDP******************************************************************* InsertPrinterList******************************************************************	EXPORT InsertPrinterListInsertPrinterList	PROC	movelong PrinterList,Temp1	lda PrinterListSize	sta ListSize	clc	adc #ListEntrySize	sta PrinterListSize	bra InsertInList	EXPORT InsertPortListInsertPortList	movelong PortList,Temp1	lda PortListSize	sta ListSize	clc	adc #ListEntrySize	sta PortListSizeInsertInList	jsr DerefTemp1ToTemp2	pha	pha	PushLong Temp1	_GetHandleSize	pla	plx	cmp ListSize	beq NoRoom	bcs ThereIsRoomNoRoom	clc	adc #2*ListEntrySize ; create enough space for 2 more drivers	phx	pha	PushLong Temp1	_SetHandleSize	jsr DerefTemp1ToTemp2ThereIsRoom	lda EntryName	and #$000F	tax	clc	adc ListSize	adc #5	tay	sep #%00100000	longa offNameLoop	lda EntryName,x	sta [Temp2],y	dey	dex	bne NameLoop	lda EntryName	and #$0F	sta [Temp2],y	dey	; now zero out the memflag byte.	lda #0	sta [Temp2],y	rep #%00100000	longa on	rtl	ENDP******************************************************************* DerefTemp1ToTemp2******************************************************************	EXPORT DerefTemp1ToTemp2DerefTemp1ToTemp2	PROC	lda [Temp1]	sta Temp2	ldy #$0002	lda [Temp1],y	sta Temp2+2	rts	ENDP******************************************************************* GetMem******************************************************************	EXPORT GetMemGetMem	PROC	pha	; space for result.	pha	pea 0	; block size	pha	PushWord UserID	; Owner.	PushWord #00	; no restrictions	pha	; invalid loc info	pha	_NewHandle	bcs AnError	pla	plx	rtsAnError	plx	plx	rts	ENDP;                copy    utils.asm******************************************************************** EqualString**     Pointer1*     Pointer2** This returns result in zero flag:**    set if equal and*    clear if not equal*******************************************************************	EXPORT EqualStringEqualString	PROC	DefineStackOrigD	wordRTS	wordPtr1	LONGPtr2	LONG	phd	tsc	tcd	sep #$30	longa off	longi off	lda [Ptr1]	cmp [Ptr2]	bne NotEqual	tayCompareLoop	lda [Ptr1],y	jsr UpperCase	sta [Ptr1],y	lda [Ptr2],y	jsr UpperCase	cmp [Ptr1],y	bne NotEqual	dey	bpl CompareLoopEqual	rep #$30	longa on	longi on	pld	pla	plx	plx	plx	plx	pha	lda #0	rtsNotEqual	rep #$30	longa on	longi on	pld	pla	plx	plx	plx	plx	pha	rts;----------------------------------------------------------;; Uppercase routine;; runs in 8 bit mode.;	longa off	longi offUpperCase	cmp #'a'	bcc NoChange	cmp #'z'	bcc ChangeIt	beq ChangeItNoChange	rtsChangeIt	sec	sbc #$20	rts	longa on	longi on	ENDP****************************************************************** CopyString** Input : Pointer To Source String*       : Pointer to Dest String** Ouput : none*****************************************************************	EXPORT CopyStringCopyString	PROC	DefineStackOrigD	wordRTLAdr	wordDestPtr	LONGSrcPtr	LONG	phd	tsc	tcd	lda #0	sep #%00100000	longa off	lda [SrcPtr]	tayLoop	lda [SrcPtr],y	sta [DestPtr],y	dey	bpl Loop	rep #$30	longa on	longi on	pld	pla	plx	plx	plx	plx	pha	rts	ENDP****************************************************************** AppendString** Input : Pointer To Orig String*       : Pointer to New String** Ouput : none** New string is appended to orig string*****************************************************************	EXPORT AppendStringAppendString	PROC	DefineStackOrigD	wordRTLAdr	wordNewPtr	LONGOrigPtr	LONG	phd	tsc	tcd	sep #%00110000	longa off	longi off	lda [OrigPtr]	; get orig length and put in x	tax	ldy #$01	; start y at 1 for new stringLoop	tya	; See if we are done with new	cmp [NewPtr]	; string by comparing with length	beq OneMoreTime	bcs DoneOneMoreTime	lda [NewPtr],y	; now done so get next char	phy	; save y on stack	txy	; get pointer to last char in orig str	iny	; bump by 1	sta [OrigPtr],y	; store char in orig str	tyx	; put back in x	ply	; get index to new off stack	iny	; bump by 1 and try	again	bra LoopDone	txa	; now update new length pointer	sta [OrigPtr]	rep #$30	longa on	longi on	pld	pla	plx	plx	plx	plx	pha	rts	ENDP******************************************************************** Cursor Stuff** These are public entry points to these common routines that* are used so often	that it pays to have a simple jsr entry	point* to them rather than wasting 7 bytes every time they are called.*******************************************************************	EXPORT CursorStuffCursorStuff	PROC	EXPORT WaitCursorWaitCursor	_WaitCursor	rts	EXPORT InitCursorInitCursor	_InitCursor	rts	ENDP******************************************************************** DisposeStuff** Disposes the PrinterList handle and the PortList handle.*******************************************************************	EXPORT DisposeStuffDisposeStuff	PROC	EXPORT DisposePrinterListDisposePrinterList	lda PrinterList	ora PrinterList+2	beq Done	PushLong PrinterList	_DisposeHandle	stz PrinterList	stz PrinterList+2Done	rts	EXPORT DisposePortListDisposePortList	lda PortList	ora PortList+2	beq Done	PushLong PortList	_DisposeHandle	stz PortList	stz PortList+2	rts	ENDP;                copy    exits	EXPORT ExitExit	PROC	EXPORT exit20exit20	tax	lda 5,s	sta 25,s	lda 3,s	sta 23,s	lda 1,s	sta 21,s	tsc	clc	adc #20	tcs	txa	brl exit0	EXPORT Exit16Exit16	tax	lda 5,s	sta 21,s	lda 3,s	sta 19,s	lda 1,s	sta 17,s	tsc	clc	adc #16	tcs	txa	brl Exit0	EXPORT Exit14Exit14	tax	lda 5,s	sta 19,s	lda 3,s	sta 17,s	lda 1,s	sta 15,s	tsc	clc	adc #14	tcs	txa	brl Exit0	EXPORT Exit12Exit12	tax	lda 5,s	sta 17,s	lda 3,s	sta 15,s	lda 1,s	sta 13,s	tsc	clc	adc #12	tcs	txa	bra Exit0	EXPORT Exit10Exit10	tax	lda 5,s	sta 15,s	lda 3,s	sta 13,s	lda 1,s	sta 11,s	tsc	clc	adc #10	tcs	txa	bra Exit0	EXPORT Exit8Exit8	tax	;Standard 8 bytes input exit	lda 5,s	sta 13,s	lda 3,s	sta 11,s	lda 1,s	sta 9,s	pla	pla	pla	pla	txa	brl Exit0	EXPORT Exit6Exit6	tax	;Standard 6 bytes input exit	lda 5,s	sta 11,s	lda 3,s	sta 9,s	lda 1,s	sta 7,s	pla	pla	pla	txa	brl Exit0	EXPORT Exit4Exit4	tax	;Standart 4 bytes input exit	lda 5,s	sta 9,s	lda 3,s	sta 7,s	lda 1,s	sta 5,s	pla	pla	txa	brl Exit0	EXPORT Exit2Exit2	tax	;Standard 2 bytes input exit	lda 5,s	sta 7,s	lda 3,s	sta 5,s	lda 1,s	sta 3,s	pla	txa	EXPORT Exit0Exit0	cmp #1	;Standard 0 byte input exit	rtl	ENDP;                copy    insertdisk.asm******************************************************************** InsertDisk** This routine puts	up an insert system	disk dialog and allows* the user to press	OK or CANCEL.*******************************************************************	EXPORT InsertDiskInsertDisk	PROC	_GetBootVol BootVolParams	_ObscureCursor	pha	PushWord StartX	PushWord StartY	PushLong #InsertDiskStr	PushLong #VolNameStr	PushLong #OKButtonStr	PushLong #CancelButtonStr	_TLMountVolume	pla	cmp #1	bne Done	clcDone	rtsBootVolParams	DC.L VolNameStrVolNameStr	DS.B 16StartX	DC.W 10StartY	DC.W 25	ENDP;                copy    DATA.ASM******************************************************************* Hopefully, we will find a way to get rid of this.******************************************************************	EXPORT SillyDataSillyData	PROC	EXPORT DispatchAdrDispatchAdr		; this is address of the	DS.B 4	; printer driver in	memory	EXPORT DPortAdrDPortAdr		; this is address of port	DS.B 4	; driver in memory	EXPORT PrinterListPrinterList		; this is handle to list of	DS.B 4	; printers on disk	EXPORT PortListPortList		; this is handle to list of	DS.B 4	; ports on disk.	EXPORT PrinterHandlePrinterHandle		; handle to list of printer names	DS.B 4	EXPORT ZoneHandleZoneHandle		; handle to list of zone names	DS.B 4;---------------------------